<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Active Satellites in Earth Orbit — 2026 Catalog Analysis</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
  :root {
    --bg: #f8f9fb;
    --card: #ffffff;
    --text: #1a1a2e;
    --muted: #6b7280;
    --accent: #2563eb;
    --accent2: #7c3aed;
    --accent3: #059669;
    --border: #e5e7eb;
    --kpi-bg: #eef2ff;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
  }
  .container { max-width: 1200px; margin: 0 auto; padding: 20px 32px 60px; }
  header {
    background: linear-gradient(135deg, #1e1b4b 0%, #1e3a5f 100%);
    color: #fff;
    padding: 48px 32px 40px;
    margin-bottom: 0;
  }
  header h1 { font-size: 2rem; font-weight: 700; letter-spacing: -0.5px; }
  header .subtitle { color: #94a3b8; margin-top: 8px; font-size: 1.05rem; }
  header .meta { color: #64748b; margin-top: 16px; font-size: 0.85rem; }

  /* KPI strip */
  .kpi-strip {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin: -28px 32px 32px;
    max-width: 1200px;
    margin-left: auto;
    margin-right: auto;
    padding: 0 32px;
    position: relative;
    z-index: 2;
  }
  .kpi-card {
    background: var(--card);
    border-radius: 12px;
    padding: 20px 18px;
    box-shadow: 0 4px 24px rgba(0,0,0,0.08);
    text-align: center;
  }
  .kpi-card .value {
    font-size: 2rem;
    font-weight: 800;
    color: var(--accent);
    line-height: 1.1;
  }
  .kpi-card .label {
    font-size: 0.78rem;
    color: var(--muted);
    margin-top: 6px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-weight: 600;
  }

  /* Sections */
  .section {
    background: var(--card);
    border-radius: 12px;
    padding: 32px;
    margin-bottom: 24px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.04);
  }
  .section h2 {
    font-size: 1.35rem;
    font-weight: 700;
    margin-bottom: 16px;
    color: var(--text);
    border-left: 4px solid var(--accent);
    padding-left: 12px;
  }
  .section h3 {
    font-size: 1.05rem;
    font-weight: 600;
    margin: 24px 0 12px;
    color: var(--text);
  }
  .section p, .section li {
    color: #374151;
    font-size: 0.95rem;
    margin-bottom: 8px;
  }
  .section ul { padding-left: 20px; }

  /* Chart containers */
  .chart-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin: 20px 0;
  }
  .chart-box {
    position: relative;
    background: #fafbfc;
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 20px;
  }
  .chart-box.full { grid-column: 1 / -1; }
  .chart-box h4 {
    font-size: 0.88rem;
    font-weight: 600;
    color: var(--muted);
    margin-bottom: 12px;
    text-transform: uppercase;
    letter-spacing: 0.3px;
  }
  canvas { max-width: 100%; }

  /* Tables */
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
    margin: 16px 0;
  }
  th, td {
    padding: 10px 14px;
    text-align: left;
    border-bottom: 1px solid var(--border);
  }
  th {
    background: #f1f5f9;
    font-weight: 600;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.3px;
    color: var(--muted);
  }
  tr:hover { background: #f8fafc; }
  .num { text-align: right; font-variant-numeric: tabular-nums; }
  .highlight-row { background: #eff6ff; font-weight: 600; }

  /* Callout box */
  .callout {
    background: #fef3c7;
    border-left: 4px solid #f59e0b;
    padding: 14px 18px;
    border-radius: 0 8px 8px 0;
    margin: 16px 0;
    font-size: 0.9rem;
  }
  .callout.blue {
    background: #eff6ff;
    border-left-color: var(--accent);
  }

  /* Method note */
  .method-note {
    background: #f1f5f9;
    border-radius: 8px;
    padding: 14px 18px;
    font-size: 0.85rem;
