    text-align: center;
    padding: 32px;
    color: var(--muted);
    font-size: 0.8rem;
  }

  @media (max-width: 900px) {
    .kpi-strip { grid-template-columns: repeat(3, 1fr); }
    .chart-row { grid-template-columns: 1fr; }
